<?php
// NexaBiz Ecommerce account plus — run from Laravel project root, CLI only.
if (PHP_SAPI !== 'cli') { http_response_code(403); exit('CLI only.'); }
$root = getcwd();
if (!is_file($root.'/artisan') || !is_file($root.'/composer.json')) { fwrite(STDERR,"Run from Laravel project root.\n"); exit(1); }
$manifest = json_decode(base64_decode(''),true,512,JSON_THROW_ON_ERROR);
$backup = $root.'/storage/app/nexabiz-patch-backups/ecommerce-phase3-20261125';
$stateFile = $backup.'/state.json';
$mode = $argv[1] ?? '--dry-run';
function hashFileOrNull($path) { return is_file($path) ? hash_file('sha256',$path) : null; }
function putPatchFile($path,$data) {
    if (!is_dir(dirname($path)) && !mkdir(dirname($path),0755,true) && !is_dir(dirname($path))) throw new RuntimeException('Cannot create directory: '.dirname($path));
    $tmp = tempnam(dirname($path),'.nexa-');
    if ($tmp === false) throw new RuntimeException('Cannot create temp file: '.$path);
    if (file_put_contents($tmp,$data) !== strlen($data)) { @unlink($tmp); throw new RuntimeException('Write failed: '.$path); }
    if (!rename($tmp,$path)) { @unlink($tmp); throw new RuntimeException('Replace failed: '.$path); }
}
try {
    if ($mode === '--rollback') {
        if (!is_file($stateFile)) throw new RuntimeException('No recorded installation backup.');
        $state = json_decode(file_get_contents($stateFile),true,512,JSON_THROW_ON_ERROR);
        // Refuse to overwrite later manual changes.
        foreach ($state as $rel=>$original) {
            $current = hashFileOrNull($root.'/'.$rel);
            $patched = $manifest[$rel]['new'] === null ? null : hash('sha256',base64_decode($manifest[$rel]['new'],true));
            if ($current !== $patched && $current !== $original) throw new RuntimeException('Rollback conflict: '.$rel);
            if ($original !== null && hashFileOrNull($backup.'/files/'.$rel) !== $original) throw new RuntimeException('Backup integrity failure: '.$rel);
        }
        foreach ($state as $rel=>$original) {
            if ($original === null) { if (is_file($root.'/'.$rel) && !unlink($root.'/'.$rel)) throw new RuntimeException('Cannot delete '.$rel); }
            else putPatchFile($root.'/'.$rel,file_get_contents($backup.'/files/'.$rel));
        }
        unlink($stateFile);
        echo "Source rollback complete. Database unchanged; restore database backup separately if necessary.\n"; exit(0);
    }
    if (!in_array($mode,['--dry-run','--apply'],true)) throw new RuntimeException('Use --dry-run, --apply, or --rollback.');
    $pending=[]; $conflicts=[];
    foreach ($manifest as $rel=>$entry) {
        $data=$entry['new'] === null ? null : base64_decode($entry['new'],true);
        $actual=hashFileOrNull($root.'/'.$rel);
        if ($actual===($data === null ? null : hash('sha256',$data))) { echo "Already patched: $rel\n"; continue; }
        if ($actual!==$entry['old']) { $conflicts[]=$rel; continue; }
        $pending[$rel]=$actual; echo "Ready: $rel\n";
    }
    if ($conflicts) throw new RuntimeException("Conflicts (no changes made):\n".implode("\n",$conflicts));
    if ($mode==='--dry-run') { echo 'Dry run complete: '.count($pending)." pending file(s).\n"; exit(0); }
    if (!$pending) { echo "Patch already installed.\n"; exit(0); }
    if (is_file($stateFile)) throw new RuntimeException('An existing backup state was found; rollback before reapplying.');
    foreach ($pending as $rel=>$original) {
        if ($original!==null) putPatchFile($backup.'/files/'.$rel,file_get_contents($root.'/'.$rel));
    }
    putPatchFile($stateFile,json_encode($pending,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));
    try {
        foreach ($pending as $rel=>$original) { if ($manifest[$rel]['new'] === null) { if (is_file($root.'/'.$rel) && !unlink($root.'/'.$rel)) throw new RuntimeException('Cannot delete '.$rel); } else putPatchFile($root.'/'.$rel,base64_decode($manifest[$rel]['new'],true)); }
    } catch (Throwable $e) {
        foreach ($pending as $rel=>$original) {
            if ($original===null) { if (is_file($root.'/'.$rel)) unlink($root.'/'.$rel); }
            else putPatchFile($root.'/'.$rel,file_get_contents($backup.'/files/'.$rel));
        }
        unlink($stateFile); throw $e;
    }
    echo 'Applied '.count($pending)." file(s). Run composer dump-autoload and php artisan optimize:clear.\n";
} catch (Throwable $e) { fwrite(STDERR,$e->getMessage()."\n"); exit(1); }
